fn rolling_max(s: &Vec<i8>) -> Option<i8> {
    if s.len() < 2 {
        return None;
    }

    // max1 will hold the largest value seen so far
    // max2 will hold the second‐largest
    let mut max1 = i8::MIN;
    let mut max2 = i8::MIN;

    for &v in s.iter() {
        if v > max1 {
            // new maximum found: demote old max1 to max2
            max2 = max1;
            max1 = v;
        } else if v > max2 {
            // v is not greater than max1, but beats the old max2
            max2 = v;
        }
    }

    Some(max2)
}

